#include <bits/stdc++.h>

using namespace std;

using PII = pair<int,int>;

const int MAX_BOARD_DIM = 11;
const int MAX_VERTEX_COUNT = 1000;
const int MAX_EDGE_COUNT = 100100;
const int LARGE_VALUE = (1<<29);

struct {
    int dest, cur_flow, cap, next;
} graph_edge[2*MAX_EDGE_COUNT];

int first_edge[MAX_VERTEX_COUNT], ptr_level[MAX_VERTEX_COUNT], level_arr[MAX_VERTEX_COUNT], bfs_list[MAX_VERTEX_COUNT];
int total_edges, total_nodes, start_node, end_node, queue_end, queue_start;

inline void setup_flow(int node_cnt, int src, int dst){
    total_nodes = node_cnt; start_node = src; end_node = dst; total_edges = 2;
    memset(first_edge, 0, (total_nodes+1)*sizeof(int));
}
inline void add_connection(int u, int v, int cap){
    graph_edge[total_edges] = {v,0,cap,first_edge[u]};
    first_edge[u] = total_edges++;
    graph_edge[total_edges] = {u,0,0,first_edge[v]};
    first_edge[v] = total_edges++;
}
inline bool create_levels(){
    memset(level_arr,0,(total_nodes+1)*sizeof(int));
    queue_end = queue_start = 0;
    bfs_list[queue_end++] = start_node;
    level_arr[start_node] = 1;
    while(queue_start<queue_end && !level_arr[end_node]){
        int u = bfs_list[queue_start++];
        for(int e = first_edge[u]; e; e = graph_edge[e].next){
            int v = graph_edge[e].dest;
            if(!level_arr[v] && graph_edge[e].cur_flow < graph_edge[e].cap){
                level_arr[v] = level_arr[u]+1;
                bfs_list[queue_end++] = v;
            }
        }
    }
    return level_arr[end_node];
}
inline int augment_path(int u, int bottleneck){
    if(u == end_node) return bottleneck;
    for(int& e = ptr_level[u]; e; e = ptr_level[u] = graph_edge[e].next){
        int v = graph_edge[e].dest;
        if(level_arr[u] < level_arr[v] && graph_edge[e].cur_flow < graph_edge[e].cap &&
           (bottleneck = augment_path(v, min(bottleneck, graph_edge[e].cap - graph_edge[e].cur_flow)))){
            graph_edge[e].cur_flow += bottleneck;
            graph_edge[e^1].cur_flow -= bottleneck;
            return bottleneck;
        }
    }
    return 0;
}
inline int compute_max_flow(){
    int result = 0, delta;
    while(create_levels()){
        memcpy(ptr_level, first_edge, (total_nodes+1)*sizeof(int));
        while((delta = augment_path(start_node, LARGE_VALUE))) result += delta;
    }
    return result;
}

int size_grid;
string grid_A[MAX_BOARD_DIM];
string grid_B[MAX_BOARD_DIM];

int dr[4] = {0,1,0,-1};
int dc[4] = {1,0,-1,0};

inline bool valid_cell(int r, int c){
    return r>=0 && c>=0 && r<size_grid && c<size_grid && grid_A[r][c]!='Y' && grid_A[r][c]!='Z';
}

int time_stamps[2][MAX_BOARD_DIM][MAX_BOARD_DIM];

void expand_bfs(int start_r, int start_c, int idx){
    memset(time_stamps[idx], 0, sizeof(time_stamps[idx]));
    time_stamps[idx][start_r][start_c] = 1;
    queue<PII> q;
    q.push({start_r, start_c});
    while(!q.empty()){
        auto [r,c] = q.front(); q.pop();
        if(idx==1 && time_stamps[0][r][c] && time_stamps[0][r][c] <= time_stamps[1][r][c]) continue;
        for(int k=0; k<4; ++k){
            int nr = r + dr[k], nc = c + dc[k];
            if(valid_cell(nr,nc) && !time_stamps[idx][nr][nc]){
                time_stamps[idx][nr][nc] = time_stamps[idx][r][c] + 1;
                q.push({nr,nc});
            }
        }
    }
}

int node_id[2][MAX_BOARD_DIM][MAX_BOARD_DIM];

int main(){
    ios::sync_with_stdio(false); cin.tie(nullptr);

    int limit_T; cin >> size_grid >> limit_T;

    int pos_Zr=0, pos_Zc=0;
    int total_node_num=0, source_v=0, sink_v=0;

    for(int r=0; r<size_grid; ++r){
        cin >> grid_A[r];
        for(int c=0; c<size_grid; ++c){
            if(grid_A[r][c]=='Z'){ pos_Zr=r; pos_Zc=c; }
            else if(grid_A[r][c]!='Y'){ total_node_num++; node_id[0][r][c]=total_node_num; }
        }
    }
    for(int r=0; r<size_grid; ++r){
        cin >> grid_B[r];
        for(int c=0; c<size_grid; ++c){
            if(grid_B[r][c]!='Y' && grid_B[r][c]!='Z'){ total_node_num++; node_id[1][r][c]=total_node_num; }
        }
    }

    total_node_num++; source_v=0; sink_v=total_node_num;
    setup_flow(total_node_num, source_v, sink_v);

    for(int r=0; r<size_grid; ++r){
        for(int c=0; c<size_grid; ++c){
            if(grid_A[r][c]!='Z' && grid_A[r][c]!='Y'){
                add_connection(source_v, node_id[0][r][c], grid_A[r][c]-'0');
                add_connection(node_id[1][r][c], sink_v, grid_B[r][c]-'0');
            }
        }
    }

    expand_bfs(pos_Zr, pos_Zc, 0);

    for(int r=0; r<size_grid; ++r){
        for(int c=0; c<size_grid; ++c){
            if(grid_A[r][c]>'0' && grid_A[r][c]<='9'){
                expand_bfs(r,c,1);
                for(int rr=0; rr<size_grid; ++rr){
                    for(int cc=0; cc<size_grid; ++cc){
                        if(grid_B[rr][cc]>'0' && grid_B[rr][cc]<='9'){
                            if(time_stamps[1][rr][cc] && (!time_stamps[0][rr][cc] || time_stamps[0][rr][cc]>=time_stamps[1][rr][cc])
                               && time_stamps[1][rr][cc]-1 <= limit_T)
                                add_connection(node_id[0][r][c], node_id[1][rr][cc], LARGE_VALUE);
                        }
                    }
                }
            }
        }
    }

    cout << compute_max_flow() << '\n';
}
